    import time

    LANGUAGE_WRAPPER = 'Let f(x) = (a x + b)/(c x + d) with nonzero real coefficients a, b, c, d, such that f(f(x)) = x for all real x except x = -d/c. It is known that f({swap_from}) = {swap_to} and f({fixed_point}) = {fixed_point}. Determine the unique real number that is not in the range of f.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We construct an involutive Möbius map by enforcing d = -a and picking integer parameters
# We will choose a fixed point p and a swap-pair (r -> s), producing an integer missing-range value X = a/c.
# Construction: pick p and k >= 1, set r = p + k, s = p - k - 1, and X = p + k(k+1).
# This ensures denominator D = 2p - r - s = 1, so X = (p^2 - r s)/D is integer.
# Also b = Y = r*s - X*(r+s) is nonzero; c=1; a=X; d=-X; all nonzero and f is involutive since d=-a.
for _ in range(1000):
    p = rng.randint(20, 300)  # keep numbers reasonably large
    k_max = max(1, p - 3)
    k = rng.randint(1, min(60, k_max))
    r = p + k
    s = p - k - 1
    # Compute X and Y
    X = p + k*(k+1)
    # Avoid any accidental degeneracy
    if X == 0:
        continue
    if r == s or r == p or s == p:
        continue
    # Domain hole equals X; ensure none of given points coincides with X
    if r == X or s == X or p == X:
        continue
    # Coefficient b (Y) must be nonzero; compute and check
    Y = r*s - X*(r + s)
    if Y == 0:
        continue
    # All good; return instance
    return {'fixed_point': p, 'swap_from': r, 'swap_to': s}
# Fallback (shouldn't happen often)
# Choose a safe deterministic instance
p = 50
k = 4
r = p + k
s = p - k - 1
return {'fixed_point': p, 'swap_from': r, 'swap_to': s}

    def verifier(assign):
# Verify structure and compute the unique value not in the range (which equals a/c for a Möbius map).
# We reconstruct a specific involutive Möbius map consistent with the assignment and confirm properties.
try:
    p = assign['fixed_point']
    r = assign['swap_from']
    s = assign['swap_to']
except Exception:
    # Missing slots
    return (False, None)
# Basic type and distinctness checks
if not all(isinstance(z, int) for z in [p, r, s]):
    # enforce integer instances for controllability
    return (False, None)
if r == s or r == p or s == p:
    return (False, None)
# From involution property for Möbius maps with nonzero b and c, we must have d = -a (so M^2 is scalar).
# Use normalized coefficients c=1 to solve for X=a/c and Y=b/c.
D = 2*p - r - s
if D == 0:
    # Generator should avoid this, but we enforce
    return (False, None)
X = (p*p - r*s) / D  # candidate a/c (unique value not in range)
# Reconstruct coefficients
a = X
c = 1.0
d = -a
Y = r*s - X*(r + s)
b = Y
# Check nonzero coefficients
if any(abs(z) < 1e-12 for z in [a, b, c, d]):
    return (False, None)
# Check domain holes do not collide with given points
domain_hole = -d/c  # equals a/c = X
if abs(domain_hole - X) > 1e-9:
    # sanity check
    return (False, None)
if any(abs(t - domain_hole) < 1e-9 for t in [p, r, s]):
    return (False, None)
# Define f and test constraints
def f(x):
    return (a*x + b) / (c*x + d)
# Validate mappings
# f(p) == p and f(r) == s
denom_p = c*p + d
denom_r = c*r + d
if abs(denom_p) < 1e-12 or abs(denom_r) < 1e-12:
    return (False, None)
if abs(f(p) - p) > 1e-9:
    return (False, None)
if abs(f(r) - s) > 1e-9:
    return (False, None)
# Involution check: for d = -a, the matrix [[a,b],[c,d]] squares to scalar, so f(f(x)) = x for all x != -d/c.
# We can sanity-check at a few random points to avoid pathological numerical issues.
test_points = [p+1, r+2, s-3, p + r - s + 0.5]
for x in test_points:
    if abs(c*x + d) < 1e-12:
        continue
    y = f(x)
    if abs(c*y + d) < 1e-12:
        # skip if intermediate hits the pole
        continue
    if abs(f(y) - x) > 1e-7:
        return (False, None)
# The unique value not in the range of a non-affine Möbius transform is y = a/c (since solving y = (ax+b)/(cx+d) gives x = (dy - b)/(a - cy), undefined when y = a/c).
answer = X
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

